declare_lint ! { #[doc = " The `for_loops_over_fallibles` lint checks for `for` loops over `Option` or `Result` values."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust"] #[doc = " let opt = Some(1);"] #[doc = " for x in opt { /* ... */}"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " Both `Option` and `Result` implement `IntoIterator` trait, which allows using them in a `for` loop."] #[doc = " `for` loop over `Option` or `Result` will iterate either 0 (if the value is `None`/`Err(_)`)"] #[doc = " or 1 time (if the value is `Some(_)`/`Ok(_)`). This is not very useful and is more clearly expressed"] #[doc = " via `if let`."] #[doc = ""] #[doc = " `for` loop can also be accidentally written with the intention to call a function multiple times,"] #[doc = " while the function returns `Some(_)`, in these cases `while let` loop should be used instead."] #[doc = ""] #[doc = " The \"intended\" use of `IntoIterator` implementations for `Option` and `Result` is passing them to"] #[doc = " generic code that expects something implementing `IntoIterator`. For example using `.chain(option)`"] #[doc = " to optionally add a value to an iterator."] pub FOR_LOOPS_OVER_FALLIBLES , Warn , "for-looping over an `Option` or a `Result`, which is more clearly expressed as an `if let`" }